export type HumanRealUserQaGroupId = keyof typeof HUMAN_REAL_USER_BANK_V2_QA_GROUPS;

export function getHumanRealUserQaGroupQuestions(
  groupId: HumanRealUserQaGroupId,
): HumanRealUserQuestion[] {
  const group = HUMAN_REAL_USER_BANK_V2_QA_GROUPS[groupId];
  if (!group) return [];
  const ids = new Set(group.question_ids);
  return HUMAN_REAL_USER_BANK_V2.filter((q) => ids.has(q.id));
}
